const input = $json.body ?? $json;

const text = (value) =>
  value === null || value === undefined
    ? ''
    : String(value).trim();

const bool = (value) =>
  typeof value === 'boolean'
    ? value
    : ['true', '1', 'yes', 'on'].includes(
        text(value).toLowerCase()
      );

const clinic_name = text(input.clinic_name);
const period_hours = Number(input.period_hours ?? 24);
const detail_limit = Number(input.detail_limit ?? 20);
const confirm_query = bool(input.confirm_query);

const errors = [];

if (
  !Number.isInteger(period_hours) ||
  period_hours < 1 ||
  period_hours > 2160
) {
  errors.push({
    field: 'period_hours',
    message: 'بازه داشبورد معتبر نیست.',
  });
}

if (
  !Number.isInteger(detail_limit) ||
  detail_limit < 1 ||
  detail_limit > 200
) {
  errors.push({
    field: 'detail_limit',
    message: 'تعداد جزئیات معتبر نیست.',
  });
}

if (confirm_query !== true) {
  errors.push({
    field: 'confirm_query',
    message: 'درخواست داشبورد باید تأیید شود.',
  });
}

return [{
  json: {
    clinic_name,
    period_hours,
    detail_limit,
    confirm_query,
    validation_status:
      errors.length === 0 ? 'valid' : 'invalid',
    errors,
  },
}];
